using System;
using System.IO;
namespace Downfield {
public static class EconomyTests {
 static int checks,failures;static void Check(bool ok,string name){checks++;if(!ok){failures++;Console.WriteLine("FAIL Economy: "+name);}}
 static Franchise Club(){return Franchise.Create(new Profile(),new Roster());}
 public static int Run(){checks=failures=0;string old=Profile.StorageOverride,folder=Path.Combine(Path.GetTempPath(),"Downfield-business-"+Guid.NewGuid().ToString("N"));Profile.StorageOverride=Path.Combine(folder,"club.txt");try{Franchise f=Club();Check(f.Business.FoodPrice==8&&f.Business.ParkingPrice==12&&f.Business.Fans==65,"new and migrated clubs get fair prices and support");f.Credits=100;f.BusinessFor(f.UserTeam);int before=f.Credits;Fixture game=f.UserGame;f.FinishGame(game.Id,21,7);Check(f.Business.LastExpenses>=10&&f.Business.LastIncome>0&&f.Credits==before+f.Business.LastIncome-f.Business.LastExpenses,"game pays real operating costs once");before=f.Credits;Check(!f.FinishGame(game.Id,21,7)&&f.Credits==before,"duplicate result cannot generate money");Check(f.Business.Fans>65&&f.Business.Security>75,"wins build fan and board confidence");
  f=Club();int fair=f.ExpectedAttendance;f.SetStadiumPrice(true,12);f.SetStadiumPrice(false,28);Check(f.Business.FoodPrice==20&&f.Business.ParkingPrice==40&&f.PriceMood<0&&f.ExpectedAttendance<fair,"expensive food and parking reduce demand and fan mood");Check(f.ExpectedAttendance/100.0*(6+f.Business.FoodPrice*.20+f.Business.ParkingPrice*.18)>fair/100.0*(6+8*.20+12*.18),"higher prices can raise first-game sales before fan support falls");Check(!f.SetStadiumPrice(true,1)&&!f.SetStadiumPrice(false,1),"prices cannot exceed limits");f.SetStadiumPrice(true,-100);f.SetStadiumPrice(false,-100);Check(f.Business.FoodPrice==0&&f.Business.ParkingPrice==0&&f.PriceMood>0,"cheap concessions improve mood and clamp at zero");
  f=Club();f.SetStadiumPrice(true,3);f.SetStadiumPrice(false,6);f.Business.Fans=48;f.Business.Security=42;f.Save();Franchise loaded=Franchise.Load(new Profile(),new Roster());Check(loaded.Business.FoodPrice==11&&loaded.Business.ParkingPrice==18&&loaded.Business.Fans==48&&loaded.Business.Security==42,"prices fans and job security survive save/load");
  Franchise fairClub=Club(),greedy=Club();fairClub.Credits=greedy.Credits=100;greedy.SetStadiumPrice(true,12);greedy.SetStadiumPrice(false,28);int seen=0;while(fairClub.Round<7&&!greedy.Fired){Fixture a=fairClub.UserGame,b=greedy.UserGame;if(a.Home==fairClub.UserTeam)seen++;fairClub.FinishGame(a.Id,21,14);greedy.FinishGame(b.Id,21,14);}Check(seen>0&&greedy.Business.Fans<fairClub.Business.Fans,"winning cannot hide repeated price gouging");
  f=Club();f.Credits=100;int losses=0;while(!f.Fired&&losses<10){Fixture a=f.UserGame;if(a==null)break;f.FinishGame(a.Id,0,35);losses++;}Check(f.Fired&&losses>=4&&losses<=8,"long losing run can get coach fired with grace period");Check(f.UserGame==null&&!f.SetStadiumPrice(true,1),"fired coach cannot run team or stadium");int wins=f.Coach.Wins,careerLosses=f.Coach.Losses,former=f.UserTeam;Check(!f.JoinClub(former),"fired coach cannot rehire himself at same club");int job=-1;foreach(LeagueTeam t in f.Teams)if(f.JobAvailable(t.Id)){job=t.Id;break;}Check(job>=0&&f.JoinClub(job)&&!f.Fired&&f.UserTeam!=former,"dismissed coach can accept a new job midseason");Check(f.Coach.Wins==wins&&f.Coach.Losses==careerLosses&&f.Coach.Losses==losses,"career follows coach after firing");Check(f.Business.Security>=60&&f.Business.JobGames==0,"new employer gives a fresh job review");
  f=Club();f.Credits=100;for(int n=0;n<11;n++)f.FinishGame(f.UserGame.Id,28,7);Check(f.Credits-100<55,"perfect regular season no longer prints easy money");before=f.Credits;f.Advance();Check(f.Credits<before,"bye still charges weekly operating costs");
  Console.WriteLine("Economy: "+checks+" checks, "+failures+" failures");return failures;
 }finally{Profile.StorageOverride=old;if(Directory.Exists(folder))Directory.Delete(folder,true);}}
}
}
